import { Group, Mesh, MeshStandardNodeMaterial, DirectionalLight, PlaneGeometry, MeshBasicNodeMaterial, Color } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // Load the GLB mesh
  const glbPromise = ctx.glbLoader.loadGLB(config.meshUrl);
  glbPromise.then((gltf) => {
    const scene = gltf.scene;
    // Ensure materials are set for machined-metal PBR (the GLB should have correct materials)
    // Optionally adjust roughness/metalness if needed, but spec says mesh has correct textures.
    group.add(scene);
  });

  // Apply cinematic primitives
  const primitivesCleanups = [];
  if (config.cinematicPrimitives) {
    for (const prim of config.cinematicPrimitives) {
      const result = ctx.primitives[prim.name](group, prim.params);
      if (result && result.cleanup) {
        primitivesCleanups.push(result.cleanup);
      }
    }
  }

  // Weighted-settle entrance animation (scale overshoot)
  const entranceTimeline = gsap.timeline();
  entranceTimeline.fromTo(group.scale, { x: 1.04, y: 1.04, z: 1.04 }, {
    x: 1, y: 1, z: 1,
    duration: 0.9,
    ease: 'power4.out'
  });

  // Hover effect: rise-in subtle 0.15 units
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(group.position, { y: 0.15, duration: 0.3, ease: 'power2.out' });

  // Attach event handlers
  group.userData.handlers = {
    pointerenter: () => {
      hoverTimeline.play();
    },
    pointerleave: () => {
      hoverTimeline.reverse();
    },
    click: () => {
      ctx.emit('hub-collection.select', {});
    }
  };

  // Load GLB
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      const scene = gltf.scene;
      group.add(scene);
    });
  }

  // Apply cinematic primitives
  const primitivesCleanups = [];
  if (config.cinematicPrimitives) {
    for (const prim of config.cinematicPrimitives) {
      const result = ctx.primitives[prim.name](group, prim.params);
      if (result && result.cleanup) {
        primitivesCleanups.push(result.cleanup);
      }
    }
  }

  // Add accent rim light (behind, from top-right)
  const rimLight = new DirectionalLight(0xff2a38, 0.8);
  rimLight.position.set(2, 1, -3);
  group.add(rimLight);

  // Cleanup function
  group.userData.cleanup = () => {
    entranceTimeline.kill();
    hoverTimeline.kill();
    primitivesCleanups.forEach(fn => fn());
    // Dispose any added meshes? The GLB scene will be disposed by the loader? We'll assume it's managed.
    // But we can traverse and dispose geometries/materials if needed.
    group.traverse((child) => {
      if (child.isMesh) {
        child.geometry.dispose();
        if (Array.isArray(child.material)) {
          child.material.forEach(m => m.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
  };

  return group;
}
